// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

contract InvMutTest is Test {
    keepMyEther c;
    function setUp() public { c = new keepMyEther(); }
    function testRegression_property() public {
        address receiver = address(new RejectEther());

        vm.deal(receiver, 1 ether);

        vm.prank(receiver);
        (bool sent, ) = address(c).call{value: 1 ether}("");
        require(sent, "deposit failed");

        vm.prank(receiver);
        (bool ok, ) = address(c).call(abi.encodeWithSignature("withdraw()"));

        assertTrue(!ok);
    }
}

contract RejectEther {
    receive() external payable {
        revert("I reject ether");
    }
}
